package fraymus.workspace;
import org.json.*;
import java.util.*;
final class SmallReport161 {
 static JSONObject data(JSONObject j){var run=j.getJSONObject("run");var target=run.getJSONObject("plan").getJSONArray("orderedTargets").getJSONObject(0);var rows=new JSONArray();for(Object raw:run.getJSONArray("samples")){var s=(JSONObject)raw;var b=s.getJSONArray("bodies").getJSONObject(0);rows.put(new JSONArray().put(s.getInt("tick")).put(s.getDouble("timeS")).put(b.getJSONArray("position")).put(b.getJSONArray("velocity")).put(b.getJSONArray("rotation")).put(s.getJSONObject("controller").getString("phase")));}return new JSONObject().put("rows",rows).put("target",target.getJSONArray("positionM")).put("metrics",run.getJSONObject("verification")).put("scope",SmallBody161.SCOPE).put("job",j.getString("id")).put("sourceHash",WorldFrames.hash(j.getJSONObject("before"))).put("plan",j.getJSONObject("plan"));}
 static JSONArray plot(JSONObject d){double minX=Double.POSITIVE_INFINITY,maxX=-minX,minZ=minX,maxZ=-minX;for(Object raw:d.getJSONArray("rows")){var p=((JSONArray)raw).getJSONArray(2);minX=Math.min(minX,p.getDouble(0));maxX=Math.max(maxX,p.getDouble(0));minZ=Math.min(minZ,p.getDouble(2));maxZ=Math.max(maxZ,p.getDouble(2));}return new JSONArray(new double[]{minX-.03,minZ-.03,maxX+.03,maxZ+.03});}
 static double[] point(JSONArray p,JSONArray limits){return new double[]{40+(p.getDouble(0)-limits.getDouble(0))*720/(limits.getDouble(2)-limits.getDouble(0)),40+(p.getDouble(2)-limits.getDouble(1))*320/(limits.getDouble(3)-limits.getDouble(1))};}
 static String summary(JSONObject d){var m=d.getJSONObject("metrics");return "Native checks "+(m.getBoolean("passed")?"passed":"failed")+"; endpoint error "+String.format(java.util.Locale.ROOT,"%.3f",m.getDouble("maxPositionErrorM")*1000)+" mm; "+m.getInt("nativeTicks")+" integration ticks.";}
 static JSONObject build(JSONObject j){var report=data(j);report.put("plot",plot(report));String encoded=MapCheckpoint.canonical(report);String html="""
 <!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Single-object motion ·161</title><style>:root{font:16px system-ui;color:#e5f4ef;background:#0b2026;color-scheme:dark}body{margin:24px}h1{font-size:36px}section{padding:20px;margin:20px 0;background:#16343c;border:1px solid #50777a;border-radius:12px}p{line-height:1.6;overflow-wrap:anywhere}svg{width:100%;max-height:360px;background:#09191f}input{width:100%}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style></head><body><small>FRAYNIX · EDITION161 · ACTUAL NATIVE MOTION</small><h1>One small object.<br>A measured, verified move.</h1><section><p id="scope"></p><p id="result"></p><p id="source"></p></section><section><h2>Original native trajectory</h2><p>Top-down X/Z path in gold; cyan marker is the selected recorded sample. Scrub the actual trace, including lift, travel, release and settling. This is simulation evidence, not camera footage.</p><svg id="plot" viewBox="0 0 800 400"><polyline id="path" fill="none" stroke="#ffc777" stroke-width="3"/><circle id="body" r="8" fill="#80dfc1"/></svg><label>Recorded sample<input id="frame" type="range" min="0" step="1" value="0"></label><p id="pose"></p></section><section><h2>Evidence and limits</h2><details><summary>Inspect numeric evidence</summary><pre id="evidence"></pre></details></section><script id="data" type="application/json">DATA161</script><script>
 const d=JSON.parse(document.querySelector('#data').textContent),$=s=>document.querySelector(s),point=p=>[40+(p[0]-d.plot[0])*720/(d.plot[2]-d.plot[0]),40+(p[2]-d.plot[1])*320/(d.plot[3]-d.plot[1])];$('#scope').textContent=d.scope;$('#source').textContent='Frozen starting state '+d.sourceHash+' · job '+d.job;$('#result').textContent='Native checks '+(d.metrics.passed?'passed':'failed')+'; endpoint error '+(d.metrics.maxPositionErrorM*1000).toFixed(3)+' mm; '+d.metrics.nativeTicks+' integration ticks.';$('#path').setAttribute('points',d.rows.map(r=>point(r[2]).join(',')).join(' '));$('#frame').max=d.rows.length-1;$('#evidence').textContent=JSON.stringify(d,null,2);function show(){const r=d.rows[Number($('#frame').value)],p=point(r[2]);$('#body').setAttribute('cx',Math.fround(p[0]));$('#body').setAttribute('cy',Math.fround(p[1]));$('#pose').textContent=JSON.stringify(r)}$('#frame').oninput=show;show();</script></body></html>
 """.replace("DATA161",encoded.replace("</","<\\/"));return new JSONObject().put("title","Small single-object motion ·161").put("sources",new JSONArray()).put("files",new JSONObject().put("index.html",html).put("motion.json",encoded));}
 static JSONObject audit(JSONObject j,JSONObject o){var d=data(j);if(!o.getString("summary").equals(summary(d)))throw new IllegalStateException("Displayed result changed");if(!o.getString("scope").equals(d.getString("scope"))||!o.getString("source").equals("Frozen starting state "+d.getString("sourceHash")+" · job "+d.getString("job")))throw new IllegalStateException("Displayed source/scope changed");var limits=plot(d);var rows=d.getJSONArray("rows");var path=o.getJSONArray("path");if(path.length()!=rows.length())throw new IllegalStateException("Missing actual path samples");for(int i=0;i<rows.length();i++){var p=rows.getJSONArray(i).getJSONArray(2);WorldVerify.close(path.getJSONArray(i).getDouble(0),(double)(float)point(p,limits)[0],.0001,"Rendered path X differs");WorldVerify.close(path.getJSONArray(i).getDouble(1),(double)(float)point(p,limits)[1],.0001,"Rendered path Z differs");}
  var states=o.getJSONArray("states");int[] selected={0,rows.length()/2,rows.length()-1};if(states.length()!=3)throw new IllegalStateException("Inspect start/middle/end");for(int i=0;i<3;i++){var s=states.getJSONObject(i);var r=rows.getJSONArray(selected[i]);var p=r.getJSONArray(2);if(s.getInt("index")!=selected[i]||!s.getBoolean("visible")||!new JSONArray(s.getString("pose")).similar(r))throw new IllegalStateException("Actual replay control/pose differs");WorldVerify.close(s.getDouble("x"),(double)(float)point(p,limits)[0],.0001,"Replay X differs");WorldVerify.close(s.getDouble("y"),(double)(float)point(p,limits)[1],.0001,"Replay Z differs");}return new JSONObject().put("passed",true).put("observed",WorldFrames.copy(o));
 }
}
